function cheapestAndWalks(n: number, edges: number[][], queries: number[][]): number[] {
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }
  return queries.map(([s, t]) => {
    const seen = new Array(n).fill(false);
    seen[s] = true;
    const q = [s];
    let cost = -1; // all bits set
    for (let h = 0; h < q.length; h++) {
      for (const [v, w] of adj[q[h]]) {
        cost &= w;
        if (!seen[v]) { seen[v] = true; q.push(v); }
      }
    }
    return seen[t] ? cost : -1;
  });
}

