    def cheapestAndWalks(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))
        out = []
        for s, t in queries:
            seen = [False] * n
            seen[s] = True
            q = deque([s])
            cost = -1  # all bits set
            while q:
                u = q.popleft()
                for v, w in adj[u]:
                    cost &= w
                    if not seen[v]:
                        seen[v] = True
                        q.append(v)
            out.append(cost if seen[t] else -1)
        return out

