function cheapestAndWalks(n: number, edges: number[][], queries: number[][]): number[] {
  const parent = Array.from({ length: n }, (_, i) => i);
  const andOf = new Array(n).fill(-1); // all bits set
  const find = (x: number): number => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  for (const [u, v, w] of edges) {
    const a = find(u), b = find(v);
    if (a !== b) { parent[a] = b; andOf[b] &= andOf[a]; }
    andOf[b] &= w;
  }
  return queries.map(([s, t]) => {
    const a = find(s);
    return a === find(t) ? andOf[a] : -1;
  });
}

