        parent = list(range(n))
        and_of = [-1] * n  # all bits set

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for u, v, w in edges:
            a, b = find(u), find(v)
            if a != b:
                parent[a] = b
                and_of[b] &= and_of[a]
            and_of[b] &= w
        out = []
        for s, t in queries:
            a = find(s)
            out.append(and_of[a] if a == find(t) else -1)
        return out

